from collections import defaultdict

class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        """Return a valid arrangement of pairs such that the second element of each
        pair matches the first element of the next pair.
        This is equivalent to finding an Eulerian path in a directed graph.
        """
        # Build adjacency list and compute degree differences (out - in)
        graph = defaultdict(list)
        degree = defaultdict(int)
        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        # Determine start node: node with out-degree - in-degree == 1
        start = None
        for node, diff in degree.items():
            if diff == 1:
                start = node
                break
        # If no such node, it's an Eulerian circuit; start from any node with edges
        if start is None:
            start = next(iter(graph)) if graph else None

        ans: List[int] = []
        def dfs(node: int):
            while graph[node]:
                dfs(graph[node].pop())
            ans.append(node)

        if start is not None:
            dfs(start)
        ans.reverse()
        # Convert node sequence to list of pairs
        return [[ans[i], ans[i + 1]] for i in range(len(ans) - 1)]"}}
